/* Dashboard connection. Loaded by the service worker before anything else.
 *
 * Do not edit this file per machine: create `config.local.js` next to it with
 * the same shape (it is gitignored and overrides these values), for example:
 *
 *   self.DRIP_CONFIG = { apiBase: 'https://my-dashboard.vercel.app', apiKey: '...' };
 */
self.DRIP_CONFIG = {
  // Where the dashboard is deployed. No trailing slash.
  apiBase: 'https://YOUR-APP.vercel.app',
  // Must equal EXTENSION_API_KEY on the dashboard.
  apiKey: 'REPLACE_ME',
  // How often to report in. Chrome allows no less than 0.5.
  heartbeatMinutes: 0.5,
  // The clock every account's day follows: when "today" starts, when the
  // nightly rest falls, when the new plan is made, what the popup shows. An
  // IANA zone name. Empty means each machine's own clock. A config.local.js
  // that leaves this out keeps this value.
  timeZone: 'Asia/Tokyo'
};
